import{_ as o,o as r,c as s,j as t,a as i,t as n,a1 as h}from"./chunks/framework.90UQlTmt.js";const m=JSON.parse('{"title":"Introduction","description":"","frontmatter":{"title":"Introduction"},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md","lastUpdated":1786660168000}'),l={name:"guide/index.md"},c={id:"frontmatter-title",tabindex:"-1"};function d(a,e,u,g,p,f){return r(),s("div",null,[t("h1",c,[i(n(a.$frontmatter.title)+" ",1),e[0]||(e[0]=t("a",{class:"header-anchor",href:"#frontmatter-title","aria-label":'Permalink to "{{ $frontmatter.title }}"'},"​",-1))]),e[1]||(e[1]=h('<p>REST Cache stores the responses your Strapi API sends, and serves them again without touching the database. When content changes, it clears what that change affected.</p><p>The second half is the difficult half, and it is what this plugin is really for. Caching is easy; knowing when to stop is not.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><p>A <code>GET</code> to a cached route is answered from the store when an entry exists for its <a href="./caching/keys.html">cache key</a>, and otherwise passed through, with the response stored on the way back.</p><p>Invalidation hooks the <strong>document service</strong>, which every write in Strapi passes through — REST, GraphQL, the content manager, the deprecated entity service, scheduled Content Releases, review workflows, and any <code>strapi.documents()</code> call of your own. A change made through any of them clears the entries it affects, including those of <a href="./invalidation/">related content types</a>.</p><p>That matters because the obvious alternative — watching HTTP routes for writes — cannot see a GraphQL mutation or a scheduled release, and drifts out of step with Strapi&#39;s route list every time that list changes.</p><h2 id="what-you-get" tabindex="-1">What you get <a class="header-anchor" href="#what-you-get" aria-label="Permalink to &quot;What you get&quot;">​</a></h2><ul><li><strong>Pluggable storage.</strong> In-memory for a single instance, <a href="./providers/redis.html">Redis</a> (or KeyDB, or Valkey) when several instances need to share one cache, or <a href="./providers/custom.html">your own</a>.</li><li><strong>Per-content-type and per-route control</strong> over lifetime, key composition and when to bypass the cache entirely.</li><li><strong>Cache keys you decide.</strong> Query parameters, request headers, and <a href="./caching/keys.html#useauth">per-caller keys</a> for authenticated traffic.</li><li><strong>Request coalescing.</strong> Concurrent requests for the same missing key make one call to the origin, not one each — which is exactly what you want on a cold start or straight after a purge.</li><li><strong>ETag and <code>304</code></strong> support, and <code>X-Cache</code> headers for seeing what happened.</li><li><strong>An <a href="./admin/">admin panel</a></strong> showing what is cached right now, with purge controls.</li></ul><h2 id="when-not-to-use-it" tabindex="-1">When not to use it <a class="header-anchor" href="#when-not-to-use-it" aria-label="Permalink to &quot;When not to use it&quot;">​</a></h2><p>This plugin caches REST responses. It does not cache GraphQL responses — though a GraphQL mutation still invalidates what it changes, so the two coexist safely.</p><p>It also will not make a slow query fast for the person who triggers it. A cache miss costs the original query plus the write to the store. What it changes is what the next reader pays.</p><h2 id="start-here" tabindex="-1">Start here <a class="header-anchor" href="#start-here" aria-label="Permalink to &quot;Start here&quot;">​</a></h2><ul><li><a href="./getting-started.html">Getting started</a> — install, configure, verify</li><li><a href="./caching/">How caching works</a></li><li><a href="./invalidation/">How invalidation works</a></li><li><a href="./reference/config.html">Configuration reference</a></li></ul>',13))])}const y=o(l,[["render",d]]);export{m as __pageData,y as default};
